<?php
/** wp eval-file tests/event-reminders.php — local only; every email is intercepted. */
if (!defined('WP_CLI') || !WP_CLI || !str_ends_with((string) wp_parse_url(home_url(), PHP_URL_HOST), '.local')) throw new RuntimeException('Installation .local uniquement.');
$ids = []; $events = []; $campaigns = []; $checks = 0; $mails = [];
$original_user = get_current_user_id(); $original_post = $_POST;
$assert = static function ($ok, $message) use (&$checks) { if (!$ok) throw new RuntimeException($message); $checks++; };
$rest = static function ($method, $path, $data = []) {
    $r = new WP_REST_Request($method, '/sdr/v1/' . $path);
    if ($method === 'GET') $r->set_query_params($data);
    else { $r->set_header('Content-Type', 'application/json'); $r->set_body(wp_json_encode($data)); }
    return rest_do_request($r);
};
$block_mail = static function ($pre, $mail) use (&$mails) { if (str_starts_with($mail['subject'], 'On joue ensemble ?')) $mails[] = $mail; return !str_contains((string) $mail['to'], 'sr-fail-'); };
add_filter('pre_wp_mail', $block_mail, PHP_INT_MAX, 2);
remove_action('transition_post_status', ['SDR_Coulisses', 'queue_new_event_email'], 10);
try {
    require_once ABSPATH . 'wp-admin/includes/user.php';
    global $wpdb;
    $prefix = 'sr-event-' . wp_generate_password(10, false, false);
    $make_user = static function ($suffix, $role = 'sdr_member', $roles = ['joueur'], $opt_in = true) use (&$ids, $prefix) {
        $id = wp_insert_user(['user_login' => $prefix . $suffix, 'user_email' => ($suffix === '7' ? 'sr-fail-' : '') . $prefix . $suffix . '@example.org', 'user_pass' => wp_generate_password(40), 'display_name' => 'Essai ' . $suffix, 'first_name' => $suffix === '0' ? 'Alice & Bob' : 'Essai', 'role' => $role, 'meta_input' => ['sdr_roles' => $roles, 'sdr_stage_opt_in' => $opt_in]]);
        if (is_wp_error($id)) throw new RuntimeException($id->get_error_message());
        $ids[] = $id; return $id;
    };
    $organizer = $make_user('org', 'sdr_organizer', [], false);
    $other = $make_user('other', 'sdr_organizer', [], false);
    $admin = $make_user('admin', 'administrator', [], false);
    $members = [];
    for ($i = 0; $i < 8; $i++) $members[] = $make_user((string) $i, 'sdr_member', $i === 0 ? ['joueur', 'mc'] : ($i === 1 ? ['dj'] : ['joueur']));
    $not_opted_in = $make_user('optout', 'sdr_member', ['mc'], false);
    $no_roles = $make_user('noroles', 'sdr_member', []);
    $demo = $make_user('demo'); update_user_meta($demo, 'sdr_demo', true);
    $outsider = $make_user('outsider', 'subscriber');
    $responded = $make_user('answered');
    $date = (new DateTimeImmutable('today', wp_timezone()))->modify('+20 days')->format('Y-m-d');
    foreach (['Un spectacle & des amis', 'Autre spectacle'] as $title) $events[] = wp_insert_post(['post_type' => 'sdr_event', 'post_status' => 'publish', 'post_title' => $title, 'meta_input' => ['_sdr_date' => $date, '_sdr_time' => '20:30', '_sdr_call_time' => '19:00', '_sdr_capacity_joueur' => 3, '_sdr_capacity_mc' => 1, '_sdr_capacity_dj' => 1]]);
    $event = $events[0]; $root = 'events/' . $event . '/reminders';
    SDR_Coulisses::save_response($event, $responded, ['availability' => 'no', 'roles' => []]);
    $audience = SDR_Event_Reminders::candidates($event)['users'];
    $assert(count(array_intersect(array_keys($audience), $members)) === 8, 'Tous les profils volontaires sans réponse sont candidats');
    foreach ([$not_opted_in, $no_roles, $demo, $outsider, $responded] as $uid) $assert(!isset($audience[$uid]), 'Profils non admissibles exclus : ' . $uid);
    $assert($audience[$members[0]]['roles'] === ['joueur', 'mc'] && $audience[$members[1]]['roles'] === ['dj'], 'Rôles exacts du profil exposés à la sélection');
    foreach (['sdr@sdr.fr', 'sdr@sdr.com', 'personne@example.invalid', 'personne@example.test'] as $email) $assert(!SDR_Event_Reminders::personal_email((object) ['user_email' => $email]), 'Adresse de remplacement exclue : ' . $email);
    $assert(SDR_Coulisses::profile($no_roles)['roles'] === [], 'Un profil sans rôle coché reste sans rôle dans les deux interfaces');
    $assert(!SDR_Coulisses::profile($not_opted_in)['stageOptIn'], 'OK pour la scène décoché par défaut');
    wp_set_current_user(0); $assert($rest('GET', $root)->get_status() === 401, 'Liste privée sans connexion');
    wp_set_current_user($members[0]); $assert($rest('GET', $root)->get_status() === 403 && $rest('POST', $root)->get_status() === 403, 'Membre sans accès aux relances');
    $profile_payload = ['roles' => ['mc'], 'diet' => 'unspecified', 'experience' => '', 'description' => '', 'likes' => [], 'dislikes' => [], 'stageOptIn' => true];
    wp_set_current_user($not_opted_in);
    $profile = $rest('POST', 'profile', $profile_payload);
    $assert($profile->get_status() === 200 && $profile->get_data()['stageOptIn'], 'Le membre peut activer OK pour la scène');
    $assert(isset(SDR_Event_Reminders::candidates($event)['users'][$not_opted_in]), 'Activation appliquée au filtre des destinataires');
    $profile = $rest('POST', 'profile', array_replace($profile_payload, ['stageOptIn' => 'yes']));
    $assert($profile->get_status() === 400, 'Choix de contact malformé refusé');
    $rest('POST', 'profile', array_replace($profile_payload, ['stageOptIn' => false]));
    $assert(!SDR_Coulisses::profile($not_opted_in)['stageOptIn'], 'Le membre peut retirer son souhait de contact');
    wp_set_current_user($admin);
    ob_start(); SDR_Coulisses::user_fields(get_userdata($not_opted_in)); $fields = ob_get_clean();
    $assert(str_contains($fields, 'name="sdr_stage_opt_in"') && str_contains($fields, 'OK pour la scène'), 'Case présente dans le profil WordPress');
    $_POST = ['sdr_user_nonce' => wp_create_nonce('sdr_user'), 'sdr_roles' => ['mc'], 'sdr_stage_opt_in' => '1'];
    SDR_Coulisses::save_user_fields($not_opted_in); $assert((bool) get_user_meta($not_opted_in, 'sdr_stage_opt_in', true), 'Activation depuis WordPress');
    unset($_POST['sdr_stage_opt_in']); SDR_Coulisses::save_user_fields($not_opted_in); $assert(!get_user_meta($not_opted_in, 'sdr_stage_opt_in', true), 'Désactivation depuis WordPress'); $_POST = $original_post;
    wp_set_current_user($organizer);
    $assert($rest('GET', $root)->get_status() === 200, 'Liste accessible à l’organisation');
    $assert($rest('POST', $root, ['requestId' => 'request-invalid-selection', 'recipients' => [$not_opted_in]])->get_status() === 409, 'Destinataire hors liste refusé');
    $assert($rest('POST', $root, ['requestId' => 'request-empty-selection', 'recipients' => []])->get_status() === 400, 'Sélection vide refusée');
    $payload = ['requestId' => 'request-valid-selection-123', 'recipients' => $members];
    $created = $rest('POST', $root, $payload);
    $assert($created->get_status() === 200 && $created->get_data()['total'] === 8, 'Envoi préparé avec la sélection exacte');
    $campaign = $created->get_data()['id']; $campaigns[] = $campaign;
    $assert($rest('POST', $root, $payload)->get_data()['id'] === $campaign, 'Création idempotente après une réponse réseau perdue');
    $assert($rest('POST', $root, array_replace($payload, ['requestId' => 'request-another-selection-123']))->get_status() === 409, 'Deux campagnes simultanées bloquées');
    wp_set_current_user($other); $assert($rest('POST', $root . '/' . $campaign . '/send')->get_status() === 404, 'Autre organisateur sans accès à la campagne');
    wp_set_current_user($organizer);
    $assert($rest('POST', 'events/' . $events[1] . '/reminders/' . $campaign . '/send')->get_status() === 404, 'Campagne non transférable à un autre spectacle');
    $batch = $rest('POST', $root . '/' . $campaign . '/send')->get_data();
    $assert($batch['accepted'] === 5 && $batch['pending'] === 3 && count($mails) === 5, 'Transmission par lots de cinq');
    update_user_meta($members[5], 'sdr_stage_opt_in', false);
    SDR_Coulisses::save_response($event, $members[6], ['availability' => 'no', 'roles' => []]);
    $batch = $rest('POST', $root . '/' . $campaign . '/send')->get_data();
    $assert($batch['accepted'] === 5 && $batch['skipped'] === 2 && $batch['failed'] === 1 && !$batch['pending'], 'Nouvelles réponses et retrait du souhait de contact revérifiés avant envoi');
    wp_cache_delete(SDR_Event_Reminders::PREFIX . $campaign, 'options');
    $persisted = get_option(SDR_Event_Reminders::PREFIX . $campaign);
    $assert(SDR_Event_Reminders::summary($persisted) === $batch, 'Bilan réellement enregistré hors cache');
    $rest('POST', $root . '/' . $campaign . '/send');
    $assert(count($mails) === 6, 'Reprise sans double envoi');
    $assert(count(array_unique(array_column($mails, 'to'))) === 6, 'Un email distinct par personne sélectionnée');
    $assert(str_contains($mails[0]['message'], 'Alice &amp; Bob') && str_contains($mails[0]['message'], 'OK, je me lance') && str_contains($mails[0]['message'], 'Je ne suis pas dispo'), 'Email HTML personnalisé avec deux boutons');
    preg_match('/href="([^"]*sdr-reponse[^"]*)"/', $mails[0]['message'], $link);
    parse_str(wp_parse_url(html_entity_decode($link[1], ENT_QUOTES, 'UTF-8'), PHP_URL_QUERY), $query);
    $credentials = ['event' => $query['spectacle'], 'user' => $query['membre'], 'token' => $query['cle']];
    $stored = get_user_meta($members[0], SDR_Event_Reminders::token_key($event), true);
    $assert(!in_array($query['cle'], $stored, true) && hash_equals($stored['hash'], hash('sha256', $query['cle'])), 'Seule l’empreinte du secret est conservée');
    $assert($stored['expires'] <= time() + 14 * DAY_IN_SECONDS, 'Lien limité à quatorze jours au plus');
    wp_set_current_user(0);
    $assert(!is_wp_error(SDR_Event_Reminders::context($credentials)) && !is_wp_error(SDR_Event_Reminders::context($credentials)) && !SDR_Event_Reminders::response($event, $members[0]), 'Consultation du lien sans mutation ni consommation');
    $assert($rest('GET', 'email-response', $credentials)->get_status() === 404, 'Aucun enregistrement par requête GET');
    $assert($rest('POST', 'email-response', array_replace($credentials, ['token' => str_repeat('a', 64), 'availability' => 'no']))->get_status() === 403, 'Secret falsifié refusé');
    $assert($rest('POST', 'email-response', array_replace($credentials, ['user' => $members[1], 'availability' => 'no']))->get_status() === 403, 'Lien lié à une seule personne');
    $assert($rest('POST', 'email-response', array_replace($credentials, ['event' => $events[1], 'availability' => 'no']))->get_status() === 403, 'Lien lié à un seul spectacle');
    $assert($rest('POST', 'email-response', $credentials + ['availability' => 'yes', 'roles' => ['dj']])->get_status() === 400, 'Rôle absent du profil refusé');
    $assert($rest('POST', 'email-response', $credentials + ['availability' => 'yes', 'roles' => []])->get_status() === 400, 'Au moins un rôle pour se proposer');
    $assert($rest('POST', 'email-response', $credentials + ['availability' => 'clear'])->get_status() === 400, 'Lien limité à la réponse, sans suppression');
    $response = $rest('POST', 'email-response', $credentials + ['availability' => 'yes', 'roles' => ['joueur', 'mc']]);
    $row = SDR_Event_Reminders::response($event, $members[0]);
    $assert($response->get_status() === 200 && $row->availability === 'yes' && json_decode($row->roles, true) === ['joueur', 'mc'], 'Proposition multirôle enregistrée sans connexion');
    $assert(get_current_user_id() === 0, 'Aucune ouverture de session ni accès au compte');
    $assert($rest('POST', 'email-response', $credentials + ['availability' => 'no'])->get_status() === 409 && SDR_Event_Reminders::response($event, $members[0])->availability === 'yes', 'Rejeu et changement de réponse par ancien lien refusés');
    $wpdb->delete($wpdb->prefix . 'sdr_responses', ['event_id' => $event, 'user_id' => $members[0]]);
    $assert($rest('POST', 'email-response', $credentials + ['availability' => 'no'])->get_status() === 409, 'Lien consommé inutilisable même après retrait de la réponse');
    $token = SDR_Event_Reminders::issue_token($event, get_userdata($members[1]));
    $negative = ['event' => $event, 'user' => $members[1], 'token' => $token['secret']];
    $assert($rest('POST', 'email-response', $negative + ['availability' => 'no'])->get_status() === 200 && SDR_Event_Reminders::response($event, $members[1])->availability === 'no', 'Indisponibilité enregistrée sans connexion');
    $token = SDR_Event_Reminders::issue_token($event, get_userdata($members[2]));
    $fresh = ['event' => $event, 'user' => $members[2], 'token' => $token['secret']];
    $key = SDR_Event_Reminders::token_key($event); $saved = get_user_meta($members[2], $key, true);
    update_user_meta($members[2], $key, array_replace($saved, ['expires' => time() - 1]));
    $assert($rest('POST', 'email-response', $fresh + ['availability' => 'no'])->get_status() === 403, 'Lien expiré refusé'); update_user_meta($members[2], $key, $saved);
    $old_email = get_userdata($members[2])->user_email;
    wp_update_user(['ID' => $members[2], 'user_email' => $prefix . '-changed@example.org']);
    $assert(is_wp_error(SDR_Event_Reminders::context($fresh)), 'Changement d’adresse révoque le lien'); wp_update_user(['ID' => $members[2], 'user_email' => $old_email]);
    update_user_meta($members[2], 'sdr_roles', []);
    $assert(is_wp_error(SDR_Event_Reminders::context($fresh)), 'Profil sans rôle ne peut plus répondre par lien'); update_user_meta($members[2], 'sdr_roles', ['joueur']);
    update_post_meta($event, '_sdr_closed', 1);
    $assert($rest('POST', 'email-response', $fresh + ['availability' => 'no'])->get_status() === 409, 'Réponses fermées respectées par le lien');
    wp_set_current_user($organizer); $assert($rest('GET', $root)->get_status() === 409, 'Relance interdite si les réponses sont fermées'); update_post_meta($event, '_sdr_closed', 0);
    update_post_meta($event, '_sdr_date', (new DateTimeImmutable('yesterday', wp_timezone()))->format('Y-m-d'));
    $assert($rest('POST', 'email-response', $fresh + ['availability' => 'no'])->get_status() === 404, 'Spectacle passé non modifiable'); update_post_meta($event, '_sdr_date', $date);
    SDR_Coulisses::save_response($event, $members[2], ['availability' => 'yes', 'roles' => ['joueur']]);
    $rest('POST', 'events/' . $event . '/selection', ['userId' => $members[2], 'role' => 'joueur']);
    $assert($rest('POST', 'email-response', $fresh + ['availability' => 'no'])->get_status() === 409 && SDR_Event_Reminders::response($event, $members[2])->selected_role === 'joueur', 'Une réponse et une sélection existantes ne sont jamais écrasées');
    $cancelled = $rest('POST', $root, ['requestId' => 'request-cancel-selection-123', 'recipients' => [$members[3]]])->get_data(); $campaigns[] = $cancelled['id'];
    $cancelled = $rest('POST', $root . '/' . $cancelled['id'] . '/cancel')->get_data();
    $assert($cancelled['cancelled'] === 1 && count($mails) === 6, 'Annuler les envois restants sans email');
    $uncertain = $rest('POST', $root, ['requestId' => 'request-uncertain-selection-123', 'recipients' => [$members[3]]])->get_data(); $campaigns[] = $uncertain['id'];
    $stored_campaign = get_option(SDR_Event_Reminders::PREFIX . $uncertain['id']);
    $stored_campaign['recipients'][$members[3]]['status'] = 'processing'; update_option(SDR_Event_Reminders::PREFIX . $uncertain['id'], $stored_campaign, false);
    $uncertain = $rest('POST', $root . '/' . $uncertain['id'] . '/send')->get_data();
    $assert($uncertain['uncertain'] === 1 && !$uncertain['pending'] && count($mails) === 6, 'Transmission incertaine signalée sans renvoi automatique');
    $renewed = SDR_Event_Reminders::issue_token($event, get_userdata($members[3]));
    $old = ['event' => $event, 'user' => $members[3], 'token' => $renewed['secret']];
    SDR_Event_Reminders::issue_token($event, get_userdata($members[3]));
    $assert(is_wp_error(SDR_Event_Reminders::context($old)), 'Une nouvelle invitation remplace l’ancien secret');
    wp_set_current_user($members[4]);
    $regular = $rest('POST', 'events/' . $event . '/response', ['availability' => 'yes', 'roles' => ['joueur']]);
    $assert($regular->get_status() === 200, 'Réponse habituelle des Coulisses conservée');
    $assert($rest('POST', 'events/' . $event . '/response', ['availability' => 'clear', 'roles' => []])->get_status() === 200, 'Retrait habituel conservé');
    WP_CLI::success($checks . ' vérifications réussies. Tous les emails interceptés, aucun envoi réel.');
} finally {
    foreach ($campaigns as $id) delete_option(SDR_Event_Reminders::PREFIX . $id);
    foreach ($events as $id) { $wpdb->delete($wpdb->prefix . 'sdr_responses', ['event_id' => $id]); wp_clear_scheduled_hook('sdr_notify_new_event', [$id]); wp_delete_post($id, true); }
    foreach ($ids as $id) wp_delete_user($id);
    $_POST = $original_post; wp_set_current_user($original_user);
    remove_filter('pre_wp_mail', $block_mail, PHP_INT_MAX);
    add_action('transition_post_status', ['SDR_Coulisses', 'queue_new_event_email'], 10, 3);
}
